"""Tests for __DISPLAY_NAME__, generated by `plexi plugin init`.

Run with:  plexi plugin test .          (from the plugin directory)

PluginHarness runs main.py as a subprocess and speaks the plugin protocol over
stdin and stdout. It needs no running Plexi host and no display.
"""
import shutil
from pathlib import Path

from plexi_sdk.testing import PluginHarness

PLUGIN = Path(__file__).resolve().parent.parent / "main.py"
if not PLUGIN.exists():
    # The SDK's own suite collects this template before `plugin init` copies
    # it into a plugin. Materialize main.py under its generated name in a
    # scratch directory and test that.
    _TEMPLATES = Path(__file__).resolve().parent
    _SCRATCH = _TEMPLATES / "__pycache__" / "scaffold_plugin"
    _SCRATCH.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(_TEMPLATES / "plugin_init.py", _SCRATCH / "main.py")
    PLUGIN = _SCRATCH / "main.py"


def _texts(frame) -> list[str]:
    """Every "text" value in a rendered frame, in tree order."""
    found: list[str] = []

    def walk(value) -> None:
        if isinstance(value, dict):
            text = value.get("text")
            if isinstance(text, str):
                found.append(text)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(frame)
    return found


def test_starts_at_zero():
    with PluginHarness(str(PLUGIN)) as h:
        assert "0" in _texts(h.run(1))


def test_button_adds_one():
    with PluginHarness(str(PLUGIN)) as h:
        h.run(1)
        h.ui_action("increment")
        assert "1" in _texts(h.run(1))


def test_plus_key_adds_one():
    with PluginHarness(str(PLUGIN)) as h:
        h.run(1)
        h.key("+")
        h.key("+")
        assert "2" in _texts(h.run(1))
